// Rendering for this feature. State changes are handled by app.js and the domain models.
function datePage(){
  const pending=state.session&&['found','waiting','agreed','declined'].includes(state.session.phase);
  const turn=yourTurn(),pendingCard=pending?`<h2 class="list-heading">Conversations</h2><div class="group-card pending-date-card"><button class="chat-row" data-action="navigate" data-view="home"><span class="mystery-avatar" aria-hidden="true">${icon('question')}${turn?'<span class="avatar-dot"></span>':''}</span><span class="row-copy"><strong>${state.session.isReschedule?'A change to your date':'Sample introduction #'+esc(state.session.person?.id||'')}</strong><span>${state.session.phase==='agreed'?'You both accepted · review and confirm':state.session.phase==='declined'?'The plans didn’t align':state.session.phase==='found'?'Choose a plan to suggest':state.session.proposal?.author==='partner'?'They suggested a new plan':'Waiting for their reply'}</span></span><span class="turn-pill ${turn?'':'waiting'}">${turn?'Your turn':'Waiting'}</span></button></div>`:'';
  if(!state.booking)return`${pageHeading('From a little spark to a first hello','Room for<br><em>a good story.</em>')}${pendingCard}${pastDatesList()}<section class="date-empty"><div class="date-empty-photo"><img src="assets/first-hello.webp" alt="Date-night inspiration, with faces out of frame"><span class="date-note">A time.<br>A place.<br><em>A yes from both.</em>${icon('heart')}</span></div><div><h2>No confirmed date yet.</h2><p>${pending?'You have a possible connection. Agree on the same plan before it lands here.':'Start with your profile, explore your type, and choose when you’re free.'}</p>${button(pending?'Review our introduction':'Explore my preferences','navigate','primary','data-view="home"','heart')}</div></section><button class="safety-link" data-action="safety">${icon('shield')} Your pace. Your choice. Always.</button>`;
  const b=state.booking,v=venueById(b.venueId);
  const phase=datePhase(b),r=Trust.record(b.matchId,state.reliabilityOverrides),mine=Trust.markerText(b.marker),theirs=Trust.markerText(r?.marker),soon=DateLifecycle.recognitionVisible(state);
  const markers=`<section class="section"><h2>How you’ll find each other</h2><div class="group-card marker-card"><div class="marker-row"><span class="row-icon">${icon('user')}</span><div><span>You</span><strong>${esc(mine||'Not set')}</strong></div></div><div class="marker-row"><span class="row-icon violet">${icon('question')}</span><div><span>Them</span><strong>${soon?esc(theirs||'Not set'):'Shown on the day of your date'}</strong></div></div></div></section>`;
  const clock=`<details class="demo-replies"><summary>Demo: jump in time ${icon('down')}</summary><p>Try each stage of the date without waiting. Real time is used otherwise.</p><div>${[['upcoming','Before the date'],['during','During the date'],['after','After the date'],['auto','Back to real time']].map(([value,label])=>button(label,'date-clock','secondary',`data-value="${value}"`,'')).join('')}</div></details>`;
  if(phase==='during')return`${pageHeading('Happening now','Enjoy your<br><em>first hello.</em>','We stay in the background. Check in whenever you like.')}${checkinCard(b)}${markers}${safetySection()}${clock}`;
  if(phase==='after')return afterDatePage(b)+clock;
  return`${pageHeading('You both said yes','It’s a date.<br><em>Almost a real one.</em>')}${pendingCard}<article class="booking-card panel"><img class="booking-photo" src="assets/${v.photo}" alt="Illustrative dining space"><div class="booking-body"><span class="success-pill">${icon('check')} Demo date confirmed</span><h2>${esc(v.name)}</h2><p class="muted">Sample introduction #${b.matchId}</p><div class="itinerary"><div>${icon('calendar')}<div><strong>${dateLabel(b.timestamp,{weekday:'long',month:'long',day:'numeric'})}</strong><span>${timeLabel(b.timestamp)} · Vancouver time · one hour</span></div></div><div>${icon('pin')}<div><strong>${esc(v.area)}, Vancouver</strong><span>Fictional sample venue</span></div></div><div>${icon('coffee')}<div><strong>${esc(Dating.billText(b.billMode))}</strong><span>~C$${v.price}/person · no payment handled here</span></div></div></div>${button('Copy date details','share','primary','','copy')}</div></article>${markers}${safetySection()}<section class="section"><h2>Before your first hello</h2><div class="panel countdown-panel"><p class="eyebrow">Time until your date</p><p class="countdown" data-countdown></p><p>Cancel free until <strong>${dateLabel(b.timestamp-86400000)} at ${timeLabel(b.timestamp-86400000)} PT.</strong></p><p class="caption">After that: example C$20 fee, and it counts as a late cancellation on your record. Safety and emergencies are exempt. No actual charges in this prototype.</p></div><div class="group-card">${row('Request a change','The original stays until you both accept a new plan','calendar','request-change')}${row('Cancel date','Review the example fee first','close','cancel')}${row('Safety and support','Share your plans. Trust your instincts.','shield','safety')}</div></section>${clock}`;
}
function datePhase(b){return DateLifecycle.phase(b,state.dateClock);}
function checkinCard(b){return`<section class="panel checkin-card ${b.checkin==='ok'?'ok':''}"><span class="empty-icon">${icon(b.checkin==='ok'?'check':'shield')}</span><h2>${b.checkin==='ok'?'Glad it’s going well.':'Safety check-in: are you okay?'}</h2><p>${b.checkin==='ok'?'We won’t ask again. Help is still one tap away.':'In a live app this arrives 45 minutes in. Only you see it.'}</p>${b.checkin==='ok'?'':button('I’m okay','checkin-ok','primary','','check')}${button('I need help','checkin-help','secondary','','shield')}</section>`;}
function safetySection(){const t=state.trusted;return`<section class="section"><h2>Your safety plan</h2><div class="panel trusted-card"><p class="body-small">Add someone you trust, then send them where and when you’re meeting.</p><div class="field-grid"><div class="field"><label for="trusted-name">Their name</label><input class="input" id="trusted-name" data-trusted-field="name" maxlength="40" autocomplete="off" value="${esc(t.name)}"></div><div class="field"><label for="trusted-contact">Their phone</label><input class="input" id="trusted-contact" data-trusted-field="contact" inputmode="tel" maxlength="20" autocomplete="off" value="${esc(t.contact)}"></div></div>${button('Share my date with them','share-trusted','secondary','','copy')}<p class="caption">Saved on this device only. In this prototype, sharing copies a message for you to send.</p></div></section>`;}
function feedbackDraft(){return DateLifecycle.feedbackFor(state);}
function fbChoice(label,action,value,selected){return`<button class="choice ${selected?'selected':''}" data-action="${action}" data-value="${esc(value)}" aria-pressed="${selected}">${esc(label)}${selected?icon('check'):''}</button>`;}
function fbError(key){return fbErrors[key]?`<p class="field-error" role="alert">${esc(fbErrors[key])}</p>`:'';}
function afterDatePage(b){
  const f=feedbackDraft(),r=Trust.record(b.matchId,state.reliabilityOverrides);
  if(DateLifecycle.canReveal(state))return`${pageHeading('It’s mutual','You both<br><em>said yes.</em>','Now you can see each other, and keep talking wherever you like.')}<section class="reveal-card"><div class="reveal-photos"><span class="reveal-photo sample" aria-label="Sample photo placeholder">${esc(r.name.charAt(0))}</span>${state.profile.photos[0]?`<img class="reveal-photo" src="${esc(state.profile.photos[0])}" alt="Your photo">`:''}</div><h2>${esc(r.name)}</h2><p class="reveal-contact">${icon('heart',true)} ${esc(r.contact)}</p><p class="body-small">They can now see your photos and ${esc(f.contact)}.</p><p class="caption">Fictional sample person and handle.</p>${button('Done','fb-finish','primary','data-value="revealed"','check')}</section>`;
  if(f.submitted&&f.their==='no')return`${pageHeading('Not this time','A good story<br><em>all the same.</em>')}<section class="panel empty-state plum-card"><span class="empty-icon">${icon('lock')}</span><h2>It wasn’t mutual.</h2><p>Your photos and contact stay private. Your individual answers aren’t displayed to them.</p>${button('Done','fb-finish','primary','data-value="no-match"','check')}</section>`;
  if(f.submitted)return`${pageHeading('Fingers crossed','Waiting on<br><em>their answer.</em>','If they say yes too, you’ll both see photos and contact details. If not, nothing is shared.')}<section class="panel empty-state"><span class="empty-icon">${icon('heart')}</span><h2>Your answer is in.</h2><p>We don’t display your private answers. Photos and contact unlock only on a mutual yes.</p></section><details class="demo-replies" open><summary>Try a demo reply ${icon('down')}</summary><p>No real partner is connected.</p><div>${button('They said yes too','fb-their','secondary',`data-value="yes" data-date-id="${esc(DateLifecycle.bookingId(b))}"`,'heart')}${button('They said no','fb-their','secondary',`data-value="no" data-date-id="${esc(DateLifecycle.bookingId(b))}"`,'close')}</div></details>`;
  const yes=f.showed==='yes';
  return`${pageHeading('After your date','How did<br><em>it go?</em>','Your decision and private note aren’t displayed to your date. Photos and contact unlock only on a mutual yes.')}<section class="panel feedback-card"><div class="field"><span class="field-label">Did they show up?</span><div class="choice-group">${fbChoice('Yes','fb-showed','yes',f.showed==='yes')}${fbChoice('No, they didn’t come','fb-showed','no',f.showed==='no')}</div>${fbError('showed')}</div>${f.showed==='no'?`<div class="info-note">${icon('flag')}We’re sorry. This saves a local demo no-show report. It never counts against you. A live service would review it.</div>`:''}${yes?`<div class="field"><span class="field-label">Rate your date</span><div class="star-row" role="group" aria-label="Rating">${[1,2,3,4,5].map(n=>`<button class="star-button ${f.stars>=n?'on':''}" data-action="fb-star" data-value="${n}" aria-label="${n} star${n>1?'s':''}" aria-pressed="${f.stars===n}">${icon('star',f.stars>=n)}</button>`).join('')}</div>${fbError('stars')}</div><div class="field"><span class="field-label">What stood out?</span><div class="choice-group">${[...Trust.goodTags,...Trust.badTags].map(t=>fbChoice(t,'fb-tag',t,f.tags.includes(t))).join('')}</div></div><button class="open-answer ${f.fake?'selected':''}" data-action="fb-fake" aria-pressed="${f.fake}">${icon('flag')} They weren’t who their profile said (report a fake profile)</button><div class="field"><span class="field-label">Would you like to see them again?</span><div class="choice-group">${fbChoice('Yes, share my contact if it’s mutual','fb-again','yes',f.again==='yes')}${fbChoice('No, thank you','fb-again','no',f.again==='no')}</div>${fbError('again')}</div>${f.again==='yes'?`<div class="field"><label for="fb-contact">What should we share if it’s mutual?</label><input class="input" id="fb-contact" data-fb-field="contact" maxlength="40" placeholder="Phone number or @handle" value="${esc(f.contact)}" autocomplete="off">${fbError('contact')}<p class="caption">Shared only if they also say yes.</p></div>`:''}`:''}<div class="field"><label for="fb-note">Anything our team should know? · private</label><textarea class="input" id="fb-note" data-fb-field="note" maxlength="300" placeholder="Never shown to them.">${esc(f.note)}</textarea></div>${button('Send my answers','fb-submit','primary','','arrow')}</section><p class="page-note">Demo answers stay on this device. Sample no-show counts update locally; no real report or review is delivered. A live service needs moderation before records change.</p>`;
}
